@mixin desktop-landscape {
  //--|🠋 Desktop (Navigation) 🠋|--\\
  $high-desk: 8rem; //--|🠈 128px for Squares 🠈|--\\
  $test-desk: 6rem; //--|🠈 96px for Squares 🠈|--\\
  $misc-desk: 4rem; //--|🠈 64px for Squares 🠈|--\\
  $tiny-desk: 3rem; //--|🠈 48px for Squares 🠈|--\\

  ol[class*='hori-X'] {
    //--|🠊 Horizontal Menus 🠈|--\\
    z-index: 1;
    display: inherit; //--|🠈 display: grid; 🠈|--\\
    grid-area: 1 / 2 / 4 / 3; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    li[class='set-top'] {
      grid-area: 1 / 1 / 2 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      //--|🠊 background: rgba(darkred, 0.25); 🠈|--\\
    }
    li[class='set-rig'] {
      position: relative;
      grid-area: 2 / 3 / 3 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\

      right: -$high-desk;
      @media screen and (max-height: 768px) {
        right: -$test-desk;
      }
      @media screen and (max-height: 480px) {
        right: -$misc-desk;
      }
      @media screen and (max-height: 360px) {
        right: -$tiny-desk;
      }
      //--|🠊 background: rgba(darkgreen, 0.25); 🠈|--\\
    }
    li[class='set-bot'] {
      grid-area: 3 / 1 / 4 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      //--|🠊 background: rgba(darkblue, 0.25); 🠈|--\\
    }
    li[class='set-lef'] {
      position: relative;
      grid-area: 2 / 1 / 3 / 2; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
      left: -$high-desk;
      @media screen and (max-height: 768px) {
        left: -$test-desk;
      }
      @media screen and (max-height: 480px) {
        left: -$misc-desk;
      }
      @media screen and (max-height: 360px) {
        left: -$tiny-desk;
      }
      //--|🠊 background: rgba(orange, 0.25); 🠈|--\\
    }

    //--|🠊 96px (Left & Right) for Design 🠈|--\\
    grid-template: //--|🠋 Width: 1920px 🠋|--\\
      8rem 1fr 8rem //--|🠈 rows 🠈|--//
      / 8rem 1fr 8rem; //--|🠈 columns 🠈|--\\
    @media screen and (max-height: 768px) {
      grid-template: //--|🠋 Width: 1366px 🠋|--\\
        6rem 1fr 6rem //--|🠈 rows 🠈|--//
        / 6rem 1fr 6rem; //--|🠈 columns 🠈|--\\
    }
    @media screen and (max-height: 480px) {
      grid-template: //--|🠋 Width: 854px 🠋|--\\
        4rem 1fr 4rem //--|🠈 rows 🠈|--//
        / 4rem 1fr 4rem; //--|🠈 columns 🠈|--\\
    }
    @media screen and (max-height: 360px) {
      grid-template: //--|🠋 Width: 640px 🠋|--\\
        3rem 1fr 3rem //--|🠈 rows 🠈|--//
        / 3rem 1fr 3rem; //--|🠈 columns 🠈|--\\
    }
  }
  ul[class*='vert-Y'] {
    //--|🠊 Vertical Buttons 🠈|--\\
    z-index: 0;
    display: inherit; //--|🠈 display: grid; 🠈|--\\
    grid-area: 1 / 1 / 4 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\

    li {
      display: inherit; //--|🠈 display: grid; 🠈|--\\
      transition: transform 250ms ease-in-out; //--|🠈 On the normal state, so it animates out and back in 🠈|--\\
      //---|===|--\\
      header[class*='expanded'] & {
        transform: scale(0);
        pointer-events: none; //--|🠈 A hidden button can't be clicked 🠈|--\\
      }

      &[class='top-lef'] {
        transform-origin: top left; //--|🠈 Shrinks into 'top-lef' corner 🠈|--\\
      }
      &[class='top-rig'] {
        transform-origin: top right; //--|🠈 Shrinks into 'top-rig' corner 🠈|--\\
      }
      &[class='bot-lef'] {
        transform-origin: bottom left; //--|🠈 Shrinks into 'bot-lef' corner 🠈|--\\
      }
      &[class='bot-rig'] {
        transform-origin: bottom right; //--|🠈 Shrinks into 'bot-rig' corner 🠈|--\\
      }
    }

    //--|🠊 96px (Left & Right) for Design 🠈|--\\
    grid-template: //--|🠋 Width: 1920px 🠋|--\\
      8rem 1fr 8rem //--|🠈 rows 🠈|--//
      / 8rem 1fr 8rem; //--|🠈 columns 🠈|--\\
    @media screen and (max-height: 768px) {
      grid-template: //--|🠋 Width: 1366px 🠋|--\\
        6rem 1fr 6rem //--|🠈 rows 🠈|--//
        / 6rem 1fr 6rem; //--|🠈 columns 🠈|--\\
    }
    @media screen and (max-height: 480px) {
      grid-template: //--|🠋 Width: 854px 🠋|--\\
        4rem 1fr 4rem //--|🠈 rows 🠈|--//
        / 4rem 1fr 4rem; //--|🠈 columns 🠈|--\\
    }
    @media screen and (max-height: 360px) {
      grid-template: //--|🠋 Width: 640px 🠋|--\\
        3rem 1fr 3rem //--|🠈 rows 🠈|--//
        / 3rem 1fr 3rem; //--|🠈 columns 🠈|--\\
    }

    li[class='top-lef'] {
      grid-area: 1 / 1 / 2 / 2; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    li[class='top-rig'] {
      grid-area: 1 / 3 / 2 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    li[class='bot-rig'] {
      grid-area: 3 / 3 / 4 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
    li[class='bot-lef'] {
      grid-area: 3 / 1 / 4 / 2; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }

  //--|🠊 96px (Left & Right) for Design 🠈|--\\
  grid-template: //--|🠋 Width: 1920px 🠋|--\\
    #{$high-desk} 1fr #{$high-desk} //--|🠈 rows 🠈|--//
    / #{$high-desk} 1fr #{$high-desk}; //--|🠈 columns 🠈|--\\
  @media screen and (max-height: 768px) {
    //--|🠊 64px (Left & Right) for Design 🠈|--\\
    grid-template: //--|🠋 Width: 1366px 🠋|--\\
      #{$test-desk} 1fr #{$test-desk} //--|🠈 rows 🠈|--//
      / #{$test-desk} 1fr #{$test-desk}; //--|🠈 columns 🠈|--\\
  }
  @media screen and (max-height: 480px) {
    //--|🠊 48px (Left & Right) for Design 🠈|--\\
    grid-template: //--|🠋 Width: 854px 🠋|--\\
      #{$misc-desk} 1fr #{$misc-desk} //--|🠈 rows 🠈|--//
      / #{$misc-desk} 1fr #{$misc-desk}; //--|🠈 columns 🠈|--\\
  }
  @media screen and (max-height: 360px) {
    //--|🠊 32px (Left & Right) for Design 🠈|--\\
    grid-template: //--|🠋 Width: 640px 🠋|--\\
      #{$tiny-desk} 1fr #{$tiny-desk} //--|🠈 rows 🠈|--//
      / #{$tiny-desk} 1fr #{$tiny-desk}; //--|🠈 columns 🠈|--\\
  }
}
