          6rem 1fr 6rem //--|🠈 rows 🠈|--//
          / 6rem 1fr 6rem; //--|🠈 columns 🠈|--\\
      }
    }
    @media screen and (max-height: 854px) {
      //--|🠊 24px (Left & Right) for Design 🠈|--\\
      grid-template: //--|🠋 Height: 640px 🠋|--\\
        #{$tiny-mobi} 1fr #{$tiny-mobi} //--|🠈 rows 🠈|--//
        / #{$tiny-mobi} 1fr #{$tiny-mobi}; //--|🠈 columns 🠈|--\\
      ol[class*='hori-X'] {
        grid-template: //--|🠋 Height: 640px 🠋|--\\
          4rem 1fr 4rem //--|🠈 rows 🠈|--//
          / 4rem 1fr 4rem; //--|🠈 columns 🠈|--\\
        li[class='set-rig'] {
          right: -$tiny-mobi;
        }
        li[class='set-lef'] {
          left: -$tiny-mobi;
        }
      }
      ul[class*='vert-Y'] {
        grid-template: //--|🠋 Height: 640px 🠋|--\\
          4rem 1fr 4rem //--|🠈 rows 🠈|--//
          / 4rem 1fr 4rem; //--|🠈 columns 🠈|--\\
      }
    }
  }
}

nav[class*='navigation-default'] {
  //--|🠋 Desktop (Landscape) 🠋|--\\
  @media screen and (orientation: landscape) {
    @include desktop-landscape();
  }
  //--|🠋 Mobile (Portrait) 🠋|--\\
  @media screen and (orientation: portrait) {
    @include mobile-portrait();
  }
  //--|🠋 Tablet (Squaring) 🠋|--\\
  @media screen and (max-aspect-ratio: 15.99/9) and (min-aspect-ratio: 9/15.99) {
    @include tablet-squaring();
  }

  display: grid;
  //--|🠊 Menu Fade 🠈|--\\
  ol[class*='hori-X'] {
    li[class*='set'] {
      opacity: 0;
      transition: opacity 1500ms;
      &:hover {
        opacity: 1;
      }
    }

    &:has(~ ul[class*='vert-Y'] .top-lef:hover) .set-top,
    &:has(~ ul[class*='vert-Y'] .top-lef:hover) .set-lef,
    &:has(~ ul[class*='vert-Y'] .top-lef:focus-within) .set-top,
    &:has(~ ul[class*='vert-Y'] .top-lef:focus-within) .set-lef {
      opacity: 0.5;
    }
    &:has(~ ul[class*='vert-Y'] .bot-rig:hover) .set-rig,
    &:has(~ ul[class*='vert-Y'] .bot-rig:focus-within) .set-rig,
    &:has(~ ul[class*='vert-Y'] .bot-rig:hover) .set-bot,
    &:has(~ ul[class*='vert-Y'] .bot-rig:focus-within) .set-bot {
      opacity: 0.5;
    }
  }
}
