//--|🠊 Canvas.meteorites.scss 🠈|--\\
//--|🠊 AI Code: Review Please 2026-11-22 · rain-main from University Tracker's index-main.scss; the <canvas> reads these values every frame 🠈|--\\
@use '../../../styles/Palettes.scss' as Palettes;

//--|🠋 Registered Properties 🠋|--\\
//--|🠊 Registered, so getComputedStyle() hands the script 'rgb(r, g, b)' and '125px', and the tones can fade between colours 🠈|--\\
@property --meteor-one {
  syntax: '<color>';
  inherits: false;
  initial-value: transparent;
}
@property --meteor-two {
  syntax: '<color>';
  inherits: false;
  initial-value: transparent;
}
@property --meteor-three {
  syntax: '<color>';
  inherits: false;
  initial-value: transparent;
}
@property --meteor-length {
  syntax: '<length>';
  inherits: false;
  initial-value: 125px;
}

@mixin desktop-landscape {
  //--|🠋 Desktop (Meteorites) 🠋|--\\
  --meteor-length: 125px; //--|🠈 1920px · the old <i> height 🠈|--\\
  @media screen and (max-height: 768px) {
    --meteor-length: 96px; //--|🠈 1366px 🠈|--\\
  }
  @media screen and (max-height: 480px) {
    --meteor-length: 64px; //--|🠈 854px 🠈|--\\
  }
  @media screen and (max-height: 360px) {
    --meteor-length: 48px; //--|🠈 640px 🠈|--\\
  }
}
@mixin mobile-portrait {
  //--|🠋 Mobile (Meteorites) 🠋|--\\
  --meteor-length: 125px; //--|🠈 1920px · the old <i> height 🠈|--\\
  @media screen and (max-width: 768px) {
    --meteor-length: 96px; //--|🠈 1366px 🠈|--\\
  }
  @media screen and (max-width: 480px) {
    --meteor-length: 64px; //--|🠈 854px 🠈|--\\
  }
  @media screen and (max-width: 360px) {
    --meteor-length: 48px; //--|🠈 640px 🠈|--\\
  }
}
@mixin tablet-squaring {
  //--|🠋 Tablet (Meteorites) 🠋|--\\
  //--|🠊 One step ahead: the long side is measured, so 1920px already takes the 1366px length 🠈|--\\
  @media screen and (orientation: landscape) {
    //--|🠊 Desktop 🠈|--\\
    @media screen and (max-width: 1920px) {
      --meteor-length: 96px;
    }
    @media screen and (max-width: 1366px) {
      --meteor-length: 64px;
    }
    @media screen and (max-width: 854px) {
      --meteor-length: 48px;
    }
  }
  @media screen and (orientation: portrait) {
    //--|🠊 Mobile 🠈|--\\
    @media screen and (max-height: 1920px) {
      --meteor-length: 96px;
    }
    @media screen and (max-height: 1366px) {
      --meteor-length: 64px;
    }
    @media screen and (max-height: 854px) {
      --meteor-length: 48px;
    }
  }
}

//--|===|--\\
@mixin meteorites-colors {
  //--|🠋 Global (Tint) 🠋|--\\
  $tint-fade: cubic-bezier(0.2, 0.8, 0.2, 1);
  transition:
    --meteor-one 500ms $tint-fade,
    --meteor-two 500ms $tint-fade,
    --meteor-three 500ms $tint-fade,
    opacity 500ms $tint-fade;
  @include mon-tint();
  @include red-tint();
  @include gre-tint();
  @include blu-tint();
  @include yel-tint();
  @include pur-tint();
  @include ora-tint();
  @include pin-tint();
  @include bro-tint();
  @include tur-tint();
}
@mixin mon-tint {
  //--|🠊 Dark Shade: light, medium and dark, the old rain on its dark gradient 🠈|--\\
  &[class*='dar_mon'] {
    --meteor-one: #{Palettes.$gray-light};
    --meteor-two: #{Palettes.$gray-medium};
    --meteor-three: #{Palettes.$gray-dark};
  }
  //--|🠊 Light Shade: the mirror, dark first 🠈|--\\
  &[class*='lig_mon'] {
    --meteor-one: #{Palettes.$gray-dark};
    --meteor-two: #{Palettes.$gray-medium};
    --meteor-three: #{Palettes.$gray-light};
  }
}
