//--|===|--\\
canvas[class*='meteorites'] {
  width: 100%;
  height: 100%;
  display: block;
  pointer-events: none; //--|🠈 Scenery: clicks fall through to what's behind it 🠈|--\\
  @include meteorites-colors();
  //--|🠊 AI Code: Review Please 2026-11-22 · Effects are heavy: .downplay hides it and its script stops, .highlight shows it while the mouse is over it 🠈|--\\
  &.downplay {
    opacity: 0;
  }
  &.highlight {
    opacity: 1;
  }
  //--|🠋 Desktop (Landscape) 🠋|--\\
  @media screen and (orientation: landscape) {
    @include desktop-landscape();
  }
  //--|🠋 Mobile (Portrait) 🠋|--\\
  @media screen and (orientation: portrait) {
    @include mobile-portrait();
  }
  //--|🠋 Tablet (Squaring) 🠋|--\\
  @media screen and (max-aspect-ratio: 15.99/9) and (min-aspect-ratio: 9/15.99) {
    @include tablet-squaring();
  }
}
