//--|🠊 AI Code: Review Please 2026-11-22 · The shared [archive] canvas grid: (colour) on top, the toggle in the middle, (shade) at the bottom, the dropdowns hidden until hovered, the toggles always visible; the <canvas> in the midground 🠈|--\\
@use '../../../../../../styles/Utilities.scss' as Utilities;

@mixin desktop-landscape {
  //--|🠊 <aside className="rotations-canvas"> 🠈|--\\
  $high-desk: 128px; //--|🠈 128px for Squares 🠈|--\\
  $test-desk: 96px; //--|🠈 96px for Squares 🠈|--\\
  $misc-desk: 64px; //--|🠈 64px for Squares 🠈|--\\
  $tiny-desk: 48px; //--|🠈 48px for Squares 🠈|--\\
  section[class*='main-fore'] {
    //--|🠊 AI Code: Review Please 2026-11-22 · One grid for every [archive] canvas page: (colour) on top, the toggle in the middle, (shade) at the bottom 🠈|--\\
    pointer-events: none; //--|🠈 Lets the hover through to the canvas in the midground 🠈|--\\
    label {
      pointer-events: auto; //--|🠈 The labels still catch their own clicks 🠈|--\\
      &.downplay {
        @include Utilities.downplay(); //--|🠈 The dropdowns only show while they're hovered 🠈|--\\
      }
    }
    label[class*='colours'] {
      grid-area: 1 / 2 / 3 / 3; //--|🠈 row-start / col-start / row-end / col-end · always the top 🠈|--\\
    }
    fieldset[class*='clarify'] {
      //--|🠊 DefaultButton.scss's darkside toggle, two squares wide 🠈|--\\
      display: flex;
      align-items: center;
      justify-content: space-around;
      place-self: center;
      grid-area: 3 / 2 / 4 / 3; //--|🠈 row-start / col-start / row-end / col-end · always the middle 🠈|--\\

      height: $high-desk;
      width: calc($high-desk * 2);
      @media screen and (max-height: 768px) {
        height: $test-desk;
        width: calc($test-desk * 2);
      }
      @media screen and (max-height: 480px) {
        height: $misc-desk;
        width: calc($misc-desk * 2);
      }
      @media screen and (max-height: 360px) {
        height: $tiny-desk;
        width: calc($tiny-desk * 2);
      }
    }
    label[class*='shades'] {
      grid-area: 4 / 2 / 6 / 3; //--|🠈 row-start / col-start / row-end / col-end · always the bottom 🠈|--\\
    }
  }
  figure[class*='main-mid'] {
    canvas[class*='rotations'] {
      grid-area: 1 / 1 / 6 / 4; //--|🠈 row-start / col-start / row-end / col-end 🠈|--\\
    }
  }
  div[class*='main-back'] {
  }
}
